static int
md_is_link_title(MD_CTX* ctx, const MD_LINE* lines, MD_SIZE n_lines, OFF beg,
                 OFF* p_end, MD_SIZE* p_beg_line_index, MD_SIZE* p_end_line_index,
                 OFF* p_contents_beg, OFF* p_contents_end)
{
    fprintf(stderr, "CALL title beg=%u n_lines=%u size=%u\\n", (unsigned)beg, (unsigned)n_lines, (unsigned)ctx->size);
    for(MD_SIZE di=0; di<n_lines && di<5; di++) fprintf(stderr, " line[%u]=%u..%u\\n", (unsigned)di, (unsigned)lines[di].beg, (unsigned)lines[di].end);
    OFF off = beg;
    CHAR closer_char;
    MD_SIZE line_index = 0;

    /* White space with up to one line break. */
    while(off < lines[line_index].end  &&  ISWHITESPACE(off))
        off++;
    if(off >= lines[line_index].end) {
        line_index++;
        if(line_index >= n_lines)
            return FALSE;
        off = lines[line_index].beg;
    }
    if(off == beg)
        return FALSE;

    *p_beg_line_index = line_index;

    /* First char determines how to detect end of it. */
    fprintf(stderr, " before switch off=%u line_index=%u end=%u ch=%d\\n", (unsigned)off, (unsigned)line_index, (unsigned)lines[line_index].end, off<ctx->size?(int)CH(off):-1);
    switch(CH(off)) {
        case _T('"'):   closer_char = _T('"'); break;
        case _T('\''):  closer_char = _T('\''); break;
        case _T('('):   closer_char = _T(')'); break;
        default:        return FALSE;
    }
    off++;

    *p_contents_beg = off;

    while(line_index < n_lines) {
        OFF line_end = lines[line_index].end;

        while(off < line_end) {
            if(CH(off) == _T('\\')  &&  off+1 < ctx->size  &&  (ISPUNCT(off+1) || ISNEWLINE(off+1))) {
                off++;
            } else if(CH(off) == closer_char) {
                /* Success. */
                *p_contents_end = off;
                *p_end = off+1;
                *p_end_line_index = line_index;
                return TRUE;
            } else if(closer_char == _T(')')  &&  CH(off) == _T('(')) {
                /* ()-style title cannot contain (unescaped '(')) */
                return FALSE;
            }

            off++;
        }

        fprintf(stderr, " finished line_index=%u off=%u line_end=%u nextbeg=%u\\n", (unsigned)line_index, (unsigned)off, (unsigned)line_end, line_index+1<n_lines?(unsigned)lines[line_index+1].beg:999999u);
        line_index++;
    }

    return FALSE;
}

